function check(title,run){test(`inventory: ${title}`,async()=>{const h=harness();try{await run(h);}finally{h.cleanup();}});}
function setup(h){h.render();for(const[k,v]of Object.entries({products:[product,service],warehouses:[warehouse,destination],suppliers:[supplier],categories:[category],taxCodes:taxes,stock:[stock],purchases:[purchase],movements:[movement],baseCurrency:'USD',loading:false,coreReady:true,loadedTabs:new Set(['overview','items','suppliers','warehouses','categories','service_sales','stock','purchases','movements'])}))h.set(k,v);return h.render();}
check('model defaults preserve stock/service, currency and nullable form behavior',h=>{assert.deepEqual(h.model.emptyItem('USD'),{sku:'',barcode:'',name:'',description:'',item_type:'stock_item',category_id:'',unit:'unit',currency:'USD',selling_price:'0',standard_cost:'0',reorder_level:'0',tax_code_id:'',track_inventory:true,allow_negative_stock:false,is_active:true,service_duration_months:''});assert.equal(h.model.emptySupplier().country_code,'BD');assert.equal(h.model.emptySupplier().currency,'BDT');assert.deepEqual(h.model.emptyWarehouse(),{code:'',name:'',address:'',is_default:false,is_active:true});});
for(const[months,expected]of [[null,'One-time'],[1,'1 month'],[12,'12 months']])check(`service duration ${months} formats without changing its value`,h=>assert.equal(h.model.serviceDurationLabel(months),expected));
check('money retains currency labeling and two fraction digits',h=>{assert.equal(h.model.money('12.5','USD'),'USD 12.50');assert.equal(h.model.money('-2','BDT'),'BDT -2.00');});
check('core loads six original resources and preserves per-currency summary values',async h=>{h.render();await h.api().loadCore();assert.deepEqual(h.requests.map(r=>r.url),['/api/inventory/dashboard-summary','/api/inventory/products?include_inactive=true','/api/inventory/warehouses','/api/inventory/categories','/api/inventory/suppliers?include_inactive=true','/api/accounting/tax/codes']);assert.deepEqual(h.state('overview').inventory_values,overview.inventory_values);assert.equal(h.state('baseCurrency'),'USD');assert.equal(h.state('products').find(p=>p.id===service.id).service_duration_months,null);assert.equal(h.state('loading'),false);});
for(const status of [401,403,422,500])check(`${status} request errors retain server details and never treat denial as success`,async h=>{h.render();h.response(()=>failure(status,'Synthetic access denied'));await assert.rejects(h.api().request('/api/inventory/products'),/Synthetic access denied/);});
check('empty and malformed response bodies have bounded parsing behavior',async h=>{h.render();h.response(()=>({ok:true,status:204,text:async()=>''}));assert.deepEqual(await h.api().request('/empty'),{});h.response(()=>({ok:false,status:500,text:async()=>'<bad>'}));await assert.rejects(h.api().request('/malformed'),/Unexpected server response/);});
for(const[tab,url]of [['purchases','/api/inventory/purchases'],['stock','/api/inventory/stock'],['movements','/api/inventory/movements']])check(`${tab} loads an existing array endpoint without invented cursor pagination`,async h=>{setup(h);await h.api().loadTab(tab,true);assert.equal(h.requests[0].url,url);assert.equal(h.state(tab).length,1);assert.equal(h.state('loadedTabs').has(tab),true);});
check('items service-catalog merge preserves products and maps duration by product identity',async h=>{setup(h);h.response(()=>success([{product_id:service.id,duration_months:12},{product_id:'unrelated',duration_months:99}]));await h.api().loadTab('items',true);assert.equal(h.state('products').length,2);assert.equal(h.state('products')[0].service_duration_months,null);assert.equal(h.state('products')[1].service_duration_months,12);});
check('cached tab avoids a second request unless forced',async h=>{setup(h);h.set('loadedTabs',new Set(['stock']));h.render();await h.api().loadTab('stock');assert.equal(h.requests.length,0);await h.api().loadTab('stock',true);assert.equal(h.requests.length,1);});
check('only active tracked stock, active suppliers/warehouses/categories enter transaction options',h=>{setup(h);h.set('products',[product,service,{...product,id:'inactive',is_active:false},{...product,id:'untracked',track_inventory:false}]);h.set('warehouses',[warehouse,{...destination,is_active:false}]);h.set('suppliers',[supplier,{...supplier,id:'inactive',is_active:false}]);h.set('categories',[category,{...category,id:'inactive',is_active:false}]);h.render();assert.deepEqual(h.api().activeStockProducts.map(p=>p.id),[product.id]);assert.deepEqual(h.api().activeSuppliers.map(p=>p.id),[supplier.id]);assert.deepEqual(h.api().activeWarehouses.map(p=>p.id),[warehouse.id]);assert.deepEqual(h.api().activeCategoryOptions,[{value:'',label:'Uncategorized'},{value:category.id,label:category.name}]);});
check('purchase options keep product currency separate from sales/purchase taxes',h=>{setup(h);h.set('products',[product,{...product,id:'bdt',currency:'BDT'}]);h.set('purchaseForm',{...h.state('purchaseForm'),currency:'USD'});h.render();assert.deepEqual(h.api().purchaseProducts.map(p=>p.id),[product.id]);assert.deepEqual(h.api().salesTaxes.map(t=>t.id),['syn-sales-tax']);assert.deepEqual(h.api().purchaseTaxes.map(t=>t.id),['syn-purchase-tax']);});
check('purchase preview preserves quantity × cost then purchase-tax calculation',h=>{setup(h);h.set('purchaseLines',[{product_id:product.id,quantity:'3',unit_cost:'10.25',tax_code_id:'syn-purchase-tax'},{product_id:product.id,quantity:'2',unit_cost:'5',tax_code_id:'syn-sales-tax'}]);h.render();assert.deepEqual(h.api().purchaseTotals,{subtotal:40.75,tax:1.5375,total:42.2875});});
check('transfer options use positive source warehouse balances and active tracked products only',h=>{setup(h);h.set('stock',[stock,{...stock,product_id:'empty',on_hand:'0'},{...stock,product_id:service.id}]);h.set('transferForm',{...h.state('transferForm'),from_warehouse_id:warehouse.id,product_id:product.id});h.render();assert.deepEqual(h.api().transferProducts.map(p=>p.id),[product.id]);assert.deepEqual(h.api().transferAvailable,stock);});
check('low-stock filter includes equality and does not aggregate warehouses',h=>{setup(h);h.set('stock',[{...stock,on_hand:'2'},{...stock,warehouse_id:destination.id,on_hand:'3'}]);h.set('lowStockOnly',true);h.render();assert.equal(h.api().filteredStock.length,1);assert.equal(h.api().filteredStock[0].warehouse_id,warehouse.id);});
for(const[name,state,search,count]of [['item SKU','filteredItems','sYn-P',1],['item category','filteredItems','synthetic category',2],['supplier vendor code','filteredSuppliers','syn-v',1],['purchase receipt','filteredPurchases','syn-r',1],['stock warehouse','filteredStock','synthetic warehouse',1],['movement reason','filteredMovements','synthetic receipt',1],['unmatched item','filteredItems','missing',0]])check(`${name} search retains its original case-insensitive fields`,h=>{setup(h);h.set('search',search);h.render();assert.equal(h.api()[state].length,count);});
check('item-type filter selects only the existing kind',h=>{setup(h);h.set('itemFilter','service');h.render();assert.deepEqual(h.api().filteredItems.map(p=>p.id),[service.id]);});
for(const value of ['0','121','1.5','bad'])check(`invalid service duration ${value} stays local`,async h=>{setup(h);h.set('itemForm',{...h.model.emptyItem('USD'),item_type:'service',service_duration_months:value});h.render();await h.api().submitItem(event());assert.equal(h.requests.length,0);assert.match(h.state('error'),/whole number between 1 and 120/);});
for(const[duration,expected]of [['',null],['1',1],['120',120]])check(`service duration ${JSON.stringify(duration)} preserves product and duration payloads`,async h=>{setup(h);h.set('itemForm',{...h.model.emptyItem('USD'),sku:'SYN',name:'Synthetic',item_type:'service',track_inventory:true,selling_price:'12.5',standard_cost:'4',reorder_level:'2',service_duration_months:duration});h.render();await h.api().submitItem(event());const writes=h.requests.filter(r=>r.options?.method);assert.equal(writes.length,2);assert.equal(writes[0].url,'/api/inventory/products');assert.deepEqual(JSON.parse(writes[0].options.body),{sku:'SYN',barcode:null,name:'Synthetic',description:null,item_type:'service',category_id:null,unit:'unit',currency:'USD',selling_price:12.5,standard_cost:4,reorder_level:2,tax_code_id:null,track_inventory:false,allow_negative_stock:false,is_active:true});assert.equal(writes[1].url,'/api/services/catalog/syn-created/duration');assert.deepEqual(JSON.parse(writes[1].options.body),{duration_months:expected});});
check('stock item numeric payload retains inventory flags without a service duration write',async h=>{setup(h);h.set('editingId',product.id);h.set('itemForm',{...h.model.emptyItem('USD'),name:'Stock',sku:'SYN',track_inventory:true,allow_negative_stock:true});h.render();await h.api().submitItem(event());const writes=h.requests.filter(r=>r.options?.method);assert.equal(writes.length,1);assert.equal(writes[0].options.method,'PATCH');assert.equal(writes[0].url,'/api/inventory/products/syn-product');const body=JSON.parse(writes[0].options.body);assert.equal(body.track_inventory,true);assert.equal(body.allow_negative_stock,true);assert.equal('service_duration_months'in body,false);});
for(const editing of [false,true])check(`supplier ${editing?'edit':'create'} keeps optional nulls and currency`,async h=>{setup(h);h.pathname('/dashboard/inventory/suppliers/'+(editing?supplier.id+'/edit':'new'));h.set('supplierForm',{...h.model.emptySupplier('USD'),name:'Supplier'});h.render();await h.api().submitSupplier(event());const r=h.requests.find(r=>r.options?.method);assert.equal(r.url,`/api/inventory/suppliers${editing?'/syn-supplier':''}`);assert.equal(r.options.method,editing?'PATCH':'POST');assert.deepEqual(JSON.parse(r.options.body),{name:'Supplier',contact_name:null,email:null,phone:null,website:null,tax_identifier:null,country_code:'BD',currency:'USD',notes:null,is_active:true});});
check('warehouse payload retains explicit default/active flags and null address',async h=>{setup(h);h.set('warehouseForm',{code:'SYN',name:'Warehouse',address:'',is_default:false,is_active:true});h.render();await h.api().submitWarehouse(event());assert.deepEqual(JSON.parse(h.requests[0].options.body),{code:'SYN',name:'Warehouse',address:null,is_default:false,is_active:true});});
check('category payload retains name and nullable description',async h=>{setup(h);h.set('categoryDraft',{id:'syn-category',name:'Category',description:''});h.render();await h.api().saveCategory(event());assert.equal(h.requests[0].url,'/api/inventory/categories/syn-category');assert.equal(h.requests[0].options.method,'PATCH');assert.deepEqual(JSON.parse(h.requests[0].options.body),{name:'Category',description:null});});
for(const[method,value,pathPart]of [['toggleItem',product,'products'],['toggleSupplier',supplier,'suppliers'],['toggleCategory',category,'categories']])check(`${method} sends only original is_active inversion`,async h=>{setup(h);await h.api()[method](value);assert.equal(h.requests[0].url,`/api/inventory/${pathPart}/${value.id}`);assert.deepEqual(JSON.parse(h.requests[0].options.body),{is_active:false});});
check('purchase rejects absent supplier or empty product lines before posting',async h=>{setup(h);h.set('purchaseForm',{...h.state('purchaseForm'),supplier_id:''});h.render();await h.api().submitPurchase(event());assert.equal(h.requests.length,0);assert.match(h.state('error'),/Choose a supplier/);h.set('purchaseForm',{...h.state('purchaseForm'),supplier_id:supplier.id});h.render();await h.api().submitPurchase(event());assert.equal(h.requests.length,0);assert.match(h.state('error'),/at least one product/);});
check('purchase receipt keeps vendor snapshot, currency, filtered lines and numeric payload',async h=>{setup(h);h.set('purchaseForm',{supplier_id:supplier.id,warehouse_id:warehouse.id,receipt_date:'2026-10-25',currency:'USD',reference:'',notes:'Synthetic receipt'});h.set('purchaseLines',[{product_id:product.id,quantity:'2',unit_cost:'10.5',tax_code_id:''},{product_id:'',quantity:'1',unit_cost:'999',tax_code_id:''}]);h.render();await h.api().submitPurchase(event());assert.equal(h.requests[0].url,'/api/inventory/purchases');assert.deepEqual(JSON.parse(h.requests[0].options.body),{supplier_name:supplier.name,vendor_id:supplier.id,warehouse_id:warehouse.id,receipt_date:'2026-10-25',currency:'USD',reference:null,notes:'Synthetic receipt',items:[{product_id:product.id,quantity:2,unit_cost:10.5,tax_code_id:null}]});});
