function nodes(n,type,out=[]){if(Array.isArray(n))n.forEach(child=>nodes(child,type,out));else if(n?.props){if(n.type===type||n.type?.name===type)out.push(n);for(const value of Object.values(n.props))if(Array.isArray(value)||value?.props)nodes(value,type,out);}return out;}
function nodeText(n){if(n==null||typeof n==='boolean')return'';if(typeof n==='number'||typeof n==='string')return String(n);if(Array.isArray(n))return n.map(nodeText).join(' ');return nodeText(n.props?.children);}
