for(const enabled of [false,true])test(`inventory real guard: enabled=${enabled} controls capture/unload/workspace listeners`,()=>{const h=inventoryGuardHarness(true,false,enabled);try{assert.equal(h.count('click'),enabled?1:0);assert.equal(h.count('beforeunload'),enabled?1:0);assert.equal(h.count(h.exitEvent),enabled?1:0);h.answer(false);assert.equal(h.requestExit(),!enabled);assert.equal(h.event('beforeunload').defaultPrevented,enabled);}finally{h.cleanup();}});
test('inventory real guard: dirty label, Cancel and failed workspace preflight preserve protection',()=>{const h=inventoryGuardHarness();try{h.answer(false);assert.equal(h.guard().navigate('/dashboard/inventory'),false);assert.equal(h.prompts[0],'You have unsaved inventory changes. Discard them and leave this page?');assert.equal(h.calls.length,0);h.answer(true);assert.equal(h.requestExit(),true);assert.equal(h.event('beforeunload').defaultPrevented,true);}finally{h.cleanup();}});
test('inventory real guard: disabling a reused controller removes prior document listeners',()=>{const h=inventoryGuardHarness();try{h.render(false,false,false);assert.equal(h.count('click'),0);assert.equal(h.count('beforeunload'),0);assert.equal(h.count(h.exitEvent),0);assert.equal(h.event('click',{target:h.anchor('/dashboard/inventory')}).defaultPrevented,false);}finally{h.cleanup();}});
test('inventory real guard: busy exit blocked and successful markClean permits one replacement navigation',()=>{const h=inventoryGuardHarness(true,true);try{assert.equal(h.guard().navigate('/dashboard/inventory',{discard:true}),false);assert.equal(h.requestExit(),false);h.guard().markClean();assert.equal(h.guard().navigate('/dashboard/inventory',{discard:true,replace:true}),true);assert.deepEqual(h.calls,[['replace','https://example.invalid/dashboard/inventory']]);}finally{h.cleanup();}});
function surface(h,file,name,extra={}){return h.load(path.join(root,`src/components/inventory/${file}.tsx`)).__test[name]({vm:h.api(),...extra});}
for(const[section,name,id]of [['items','ItemDetail',product.id],['suppliers','SupplierDetail',supplier.id],['warehouses','WarehouseDetail',warehouse.id],['purchases','PurchaseDetail',purchase.id]])check(`${section} View is a readonly document without editable inputs or a submit form`,h=>{setup(h);const tree=surface(h,'inventory-detail',name,{id});for(const type of ['input','select','textarea','form','EditorForm'])assert.equal(nodes(tree,type).length,0);assert.equal(h.requests.length,0);if(section==='purchases')assert.equal(nodes(tree,'DocumentHeader')[0].props.onEdit,undefined);});
for(const[name,id]of [['ItemDetail',product.id],['SupplierDetail',supplier.id],['WarehouseDetail',warehouse.id]])check(`${name} hides edit action when permission is absent or a write is busy`,h=>{setup(h);h.permissions(['finance.view']);h.render();assert.equal(nodes(surface(h,'inventory-detail',name,{id}),'DocumentHeader')[0].props.onEdit,undefined);h.permissions(['finance.manage']);h.set('saving',true);h.render();assert.equal(nodes(surface(h,'inventory-detail',name,{id}),'DocumentHeader')[0].props.onEdit,undefined);});
check('receipt View preserves four currency-specific amounts and only positive balances link to Payables',h=>{setup(h);let tree=surface(h,'inventory-detail','PurchaseDetail',{id:purchase.id});const facts=Object.fromEntries(nodes(tree,'Fact').map(n=>[n.props.label,nodeText(n.props.children)]));assert.equal(facts.Subtotal,'USD 20.00');assert.equal(facts.Tax,'USD 1.00');assert.equal(facts.Total,'USD 21.00');assert.equal(facts.Payable,'USD 21.00');assert.equal(nodes(tree,'NextLink')[0].props.href,'/dashboard/accounting/payables');h.set('purchases',[{...purchase,balance_due:'0'}]);h.render();tree=surface(h,'inventory-detail','PurchaseDetail',{id:purchase.id});assert.equal(nodes(tree,'NextLink').length,0);});
check('unavailable purchase identifies the bounded latest-200 source rather than inventing an empty receipt',h=>{setup(h);const tree=surface(h,'inventory-detail','PurchaseDetail',{id:'missing'});assert.equal(tree.type.name,'MissingRecord');assert.equal(tree.props.limited,true);const missing=h.load(path.join(root,'src/components/inventory/inventory-detail.tsx')).__test.MissingRecord(tree.props);assert.match(missing.props.text,/latest 200/);assert.equal(h.requests.length,0);});
check('supplier aggregate amounts do not borrow its default currency',h=>{setup(h);const tree=surface(h,'inventory-detail','SupplierDetail',{id:supplier.id});const values=Object.fromEntries(nodes(tree,'Fact').map(n=>[n.props.label,nodeText(n.props.children)]));assert.equal(values.Purchased,'50.00');assert.equal(values.Outstanding,'20.00');assert.equal(values['Default currency'],'USD');assert.match(nodeText(tree),/not verified single-currency amounts/);});
check('overview keeps separate currency ledger rows and original counts without a mixed monetary total',h=>{setup(h);h.set('overview',overview);h.render();const tree=surface(h,'inventory-register','OverviewRegister');const ledger=nodes(tree,'dl')[0];assert.equal(nodes(ledger,'dd').length,2);assert.match(nodeText(ledger),/USD 40.00/);assert.match(nodeText(ledger),/BDT 400.00/);assert.doesNotMatch(nodeText(ledger),/440/);});
check('overview low-stock action makes one atomic browse update without a transaction',h=>{setup(h);h.set('overview',overview);h.render();const tree=surface(h,'inventory-register','OverviewRegister');nodes(tree,'button').find(n=>nodeText(n).includes('Low-stock balances')).props.onClick();const url=new URL(h.navigation[0][1],'https://example.invalid');assert.equal(url.searchParams.get('tab'),'stock');assert.equal(url.searchParams.get('low'),'1');assert.equal(url.searchParams.get('search'),null);assert.equal(h.requests.length,0);});
