check('movement currency uses supplied product identity, with SKU fallback only when identity is absent',h=>{setup(h);const other={...product,id:'other',currency:'BDT'};h.set('products',[product,other]);h.set('movements',[{...movement,product_id:'other'}]);h.render();let tree=surface(h,'inventory-register','MovementsRegister');assert.match(nodeText(nodes(tree,'Cell').find(n=>n.props.label==='Unit cost')),/BDT 8.00/);h.set('movements',[{...movement,product_id:'missing'}]);h.render();tree=surface(h,'inventory-register','MovementsRegister');assert.match(nodeText(nodes(tree,'Cell').find(n=>n.props.label==='Unit cost')),/Currency unavailable/);assert.doesNotMatch(nodeText(nodes(tree,'Cell').find(n=>n.props.label==='Unit cost')),/USD|BDT/);h.set('movements',[movement]);h.render();tree=surface(h,'inventory-register','MovementsRegister');assert.match(nodeText(nodes(tree,'Cell').find(n=>n.props.label==='Unit cost')),/USD 8.00/);});
check('service-sales register reuses the existing untouched panel without duplicate writes',h=>{setup(h);h.set('tab','service_sales');h.render();const tree=h.load(path.join(root,'src/components/inventory/inventory-register.tsx')).InventoryRegister({vm:h.api()});assert.equal(nodes(tree,'ServiceSalesPanel').length,1);assert.equal(h.requests.length,0);});

check('switching to cached overview cancels an in-flight section without a stuck loading state',async h=>{setup(h);h.set('loadedTabs',new Set(['overview']));h.set('tab','movements');h.render();let resolve;h.response(()=>new Promise(r=>{resolve=r;}));const effect=h.effects.find(fn=>fn.toString().includes('if (coreReady)'));assert.ok(effect);const cleanup=effect();assert.equal(h.state('loading'),true);cleanup();h.set('tab','overview');h.render();h.effects.find(fn=>fn.toString().includes('if (coreReady)'))();assert.equal(h.state('loading'),false);resolve(success([{...movement,id:'stale-movement'}]));await settle();assert.equal(h.state('movements')[0].id,movement.id);});
check('explicit Refresh of a dirty editor cancels safely; confirmed refresh replaces the document boundary',async h=>{setup(h);h.pathname('/dashboard/inventory/items/new');h.render();h.set('itemForm',{...h.api().itemForm,name:'Unsaved'});h.render();h.confirm(false);await h.api().refresh();assert.equal(h.navigation.length,0);assert.equal(h.requests.length,0);h.confirm(true);await h.api().refresh();assert.equal(h.navigation[0][0],'navigate');assert.deepEqual(h.navigation[0][2],{discard:true,replace:true});assert.equal(h.requests.length,0);});
check('busy editor prevents Cancel and Refresh navigation',async h=>{setup(h);h.pathname('/dashboard/inventory/items/new');h.set('saving',true);h.render();h.api().closeDocument();await h.api().refresh();assert.equal(h.navigation.length,0);assert.equal(h.requests.length,0);});
check('unknown record identity and incomplete stock setup never make an editable document ready',async h=>{setup(h);h.pathname('/dashboard/inventory/items/missing/edit');h.render();assert.equal(h.api().recordExists,false);assert.equal(h.api().documentReady,false);await h.api().submitItem(event());assert.equal(h.requests.length,0);h.pathname('/dashboard/inventory/transfers/new');h.set('warehouses',[warehouse]);h.render();assert.equal(h.api().documentReady,false);assert.match(h.api().setupError,/at least two active warehouses/);});
check('service partial failure remains dirty even if fields equal their original values',async h=>{setup(h);h.pathname('/dashboard/inventory/items/syn-service/edit');h.render();assert.equal(h.api().hasChanges,false);h.response((url,options)=>url.endsWith('/duration')?failure(422,'Synthetic duration failure'):h.defaultResponse(url,options));await h.api().submitItem(event());h.render();assert.equal(h.api().hasChanges,true);assert.equal(h.state('persistedProductId'),service.id);assert.equal(h.state('documentCommitted'),false);assert.match(h.state('error'),/record is saved/);});
check('fully saved service also cannot be reposted after failed document navigation',async h=>{setup(h);h.pathname('/dashboard/inventory/items/new');h.render();h.set('itemForm',{...h.api().itemForm,name:'Service',sku:'SYN',item_type:'service',service_duration_months:'6'});h.render();h.navigationFails(true);await h.api().submitItem(event());h.render();assert.equal(h.state('documentCommitted'),true);assert.equal(h.api().hasChanges,false);await h.api().submitItem(event());assert.equal(h.requests.filter(r=>r.options?.method).length,2);assert.equal(h.requests.filter(r=>r.options?.method==='POST').length,1);});
